import java.io.*;
import java.util.*;

class Scan {
    private Deque<String> buffer = new ArrayDeque<>();
    private final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

    public <T> T next(Class<T> clazz) {
        while (true) {
            if (!buffer.isEmpty()) {
                String token = buffer.pollFirst();
                if (clazz == Integer.class) {
                    return clazz.cast(Integer.parseInt(token));
                } else if (clazz == Long.class) {
                    return clazz.cast(Long.parseLong(token));
                } else if (clazz == String.class) {
                    return clazz.cast(token);
                } else {
                    throw new RuntimeException("Unsupported type");
                }
            }
            try {
                String line = reader.readLine();
                if (line == null) throw new RuntimeException("Fail to read");
                String[] parts = line.trim().split("\\s+");
                buffer.clear();
                for (String p : parts) {
                    if (!p.isEmpty()) buffer.addLast(p);
                }
            } catch (IOException e) {
                throw new RuntimeException("Fail to read", e);
            }
        }
    }
}

public class Main {
    public static void _main() {
        Scan scan = new Scan();
        int res = 0;
        int n = scan.next(Integer.class);
        int m = scan.next(Integer.class);
        int limit = Math.max(n, m);
        for (int i = 0; i <= limit; i++) {
            for (int j = 0; j <= limit; j++) {
                if (i * i + j == n && i + j * j == m) {
                    res += 1;
                }
            }
        }
        System.out.println(res);
    }

    public static void main(String[] args) {
        Thread t = new Thread(Main::_main);
        t.start();
        try {
            t.join();
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }
}

